/// Streaming update for one assistant message, discriminated by `type`.
#[derive(Debug, Clone, PartialEq)]
pub enum AssistantMessageEvent {
	Start(AssistantStartEvent),
	TextStart(AssistantTextStartEvent),
	TextDelta(AssistantTextDeltaEvent),
	TextEnd(AssistantTextEndEvent),
	ThinkingStart(AssistantThinkingStartEvent),
	ThinkingDelta(AssistantThinkingDeltaEvent),
	ThinkingEnd(AssistantThinkingEndEvent),
	ImageEnd(AssistantImageEndEvent),
	ToolcallStart(AssistantToolCallStartEvent),
	ToolcallDelta(AssistantToolCallDeltaEvent),
	ToolcallEnd(AssistantToolCallEndEvent),
	Done(AssistantDoneEvent),
	Error(AssistantErrorEvent),
}

impl AssistantMessageEvent {
	/// Decodes from JSON, dispatching on `type`.
	pub fn from_value(value: Value) -> Result<Self, serde_json::Error> {
		let decode: fn(Value) -> Result<Self, serde_json::Error> = match value.get("type").and_then(Value::as_str) {
			Some("start") => |value| serde_json::from_value(value).map(Self::Start),
			Some("text_start") => |value| serde_json::from_value(value).map(Self::TextStart),
			Some("text_delta") => |value| serde_json::from_value(value).map(Self::TextDelta),
			Some("text_end") => |value| serde_json::from_value(value).map(Self::TextEnd),
			Some("thinking_start") => |value| serde_json::from_value(value).map(Self::ThinkingStart),
			Some("thinking_delta") => |value| serde_json::from_value(value).map(Self::ThinkingDelta),
			Some("thinking_end") => |value| serde_json::from_value(value).map(Self::ThinkingEnd),
			Some("image_end") => |value| serde_json::from_value(value).map(Self::ImageEnd),
			Some("toolcall_start") => |value| serde_json::from_value(value).map(Self::ToolcallStart),
			Some("toolcall_delta") => |value| serde_json::from_value(value).map(Self::ToolcallDelta),
			Some("toolcall_end") => |value| serde_json::from_value(value).map(Self::ToolcallEnd),
			Some("done") => |value| serde_json::from_value(value).map(Self::Done),
			Some("error") => |value| serde_json::from_value(value).map(Self::Error),
			other => {
				return Err(serde_json::Error::custom(format!("unknown AssistantMessageEvent type {other:?}")));
			}
		};
		decode(value)
	}
}

impl Serialize for AssistantMessageEvent {
	fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
		match self {
			Self::Start(member) => serialize_tagged(member, &[("type", "start")], serializer),
			Self::TextStart(member) => serialize_tagged(member, &[("type", "text_start")], serializer),
			Self::TextDelta(member) => serialize_tagged(member, &[("type", "text_delta")], serializer),
			Self::TextEnd(member) => serialize_tagged(member, &[("type", "text_end")], serializer),
			Self::ThinkingStart(member) => serialize_tagged(member, &[("type", "thinking_start")], serializer),
			Self::ThinkingDelta(member) => serialize_tagged(member, &[("type", "thinking_delta")], serializer),
			Self::ThinkingEnd(member) => serialize_tagged(member, &[("type", "thinking_end")], serializer),
			Self::ImageEnd(member) => serialize_tagged(member, &[("type", "image_end")], serializer),
			Self::ToolcallStart(member) => serialize_tagged(member, &[("type", "toolcall_start")], serializer),
			Self::ToolcallDelta(member) => serialize_tagged(member, &[("type", "toolcall_delta")], serializer),
			Self::ToolcallEnd(member) => serialize_tagged(member, &[("type", "toolcall_end")], serializer),
			Self::Done(member) => serialize_tagged(member, &[("type", "done")], serializer),
			Self::Error(member) => serialize_tagged(member, &[("type", "error")], serializer),
		}
	}
}

impl<'de> Deserialize<'de> for AssistantMessageEvent {
	fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		Self::from_value(Value::deserialize(deserializer)?).map_err(D::Error::custom)
	}
}

