/// Presentation metadata aligned positionally with `options`.
///
/// Open record: declared fields are decoded leniently (a value that does not fit stays
/// in `extra`) and every other key is kept in `extra`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct SelectOptionDetail {
	pub description: Option<String>,
	/// Every key not decoded into a declared field.
	pub extra: Map<String, Value>,
}

impl Serialize for SelectOptionDetail {
	fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
		let mut map = serializer.serialize_map(None)?;
		if let Some(value) = &self.description {
			map.serialize_entry("description", value)?;
		}
		for (key, value) in &self.extra {
			match key.as_str() {
				"description" if self.description.is_some() => continue,
				_ => {}
			}
			map.serialize_entry(key, value)?;
		}
		map.end()
	}
}

impl<'de> Deserialize<'de> for SelectOptionDetail {
	fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		let mut extra = Map::<String, Value>::deserialize(deserializer)?;
		Ok(Self {
			description: take(&mut extra, "description"),
			extra,
		})
	}
}

